// 驗簽 → 攤平 → 過濾 → 去重。四件事一起做,後面就不必再處理結構。
//
// self-host 需要環境變數 NODE_FUNCTION_ALLOW_BUILTIN=crypto。

const crypto = require('crypto');

const item = $input.first();

// ── 1. 驗簽。必須對「原始位元組」算,所以 Webhook node 的 Raw Body 一定要開。 ──
//    用解析過再 JSON.stringify 回去的字串算,會因為鍵序/escape 差異而時好時壞。
const raw = Buffer.from(item.binary.data.data, 'base64');
const signature = item.json.headers['x-hub-signature-256'];
const secret = $env.META_APP_SECRET;

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');
const a = Buffer.from(signature ?? '');
const b = Buffer.from(expected);

// 不要用 ===：字串比較會提早回傳,洩漏時間差
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('X-Hub-Signature-256 驗證失敗');
}

const payload = JSON.parse(raw.toString('utf8'));

// Instagram 的 webhook 也會進到同一個 URL,object 會是 "instagram"
if (payload.object !== 'page') return [];

// ── 2. 攤平。Meta 可以一次塞多個 entry、每個 entry 多則訊息。 ──
const staticData = $getWorkflowStaticData('global');
staticData.seenMids = staticData.seenMids || [];

const out = [];

for (const entry of payload.entry ?? []) {
  for (const event of entry.messaging ?? []) {
    const message = event.message;

    // ── 3. 過濾 ──
    // ★ is_echo 是自己送出去的回音。不濾掉會變成 bot 跟自己無限對話。
    if (!message || message.is_echo) continue;
    // 已讀/送達回報量很大,直接丟掉
    if (event.read || event.delivery) continue;
    if (typeof message.text !== 'string' || message.text.trim() === '') continue;

    // ── 4. 去重。Meta 沒在 20 秒內收到 200 就重送,連續失敗會停用 webhook。 ──
    const mid = message.mid;
    if (mid && staticData.seenMids.includes(mid)) continue;
    if (mid) staticData.seenMids.push(mid);

    out.push({
      json: {
        mid,
        pageId: entry.id,
        // PSID 是粉專範圍內的 ID,不是使用者的 Facebook UID
        psid: event.sender.id,
        text: message.text.trim(),
        timestamp: event.timestamp,
      },
    });
  }
}

staticData.seenMids = staticData.seenMids.slice(-500);
return out;

// 後端回覆 → Messenger 可送出的多則訊息。Messenger 的上限是 2000 字元。

const MESSENGER_LIMIT = 2000;
const FALLBACK = '抱歉,系統忙線中,請稍後再試一次。';

function splitMessage(text, limit) {
  const chars = Array.from(String(text ?? ''));
  if (chars.length === 0) return [];
  if (chars.length <= limit) return [chars.join('')];

  const chunks = [];
  let rest = chars;
  while (rest.length > limit) {
    const windowText = rest.slice(0, limit).join('');
    let cut = -1;
    for (const [pattern, minRatio] of [
      [/\n\n/g, 0.3],
      [/\n/g, 0.3],
      [/[。！？!?](?=\s|$)/g, 0.5],
      [/\s/g, 0.7],
    ]) {
      let last = -1;
      for (const m of windowText.matchAll(pattern)) last = m.index + m[0].length;
      if (last > limit * minRatio) { cut = Array.from(windowText.slice(0, last)).length; break; }
    }
    if (cut <= 0) cut = limit;
    chunks.push(rest.slice(0, cut).join('').trimEnd());
    rest = rest.slice(cut);
    while (rest.length && /\s/.test(rest[0])) rest = rest.slice(1);
  }
  if (rest.length) chunks.push(rest.join('').trimEnd());
  return chunks.filter((c) => c.length > 0);
}

// HTTP 節點開了 fullResponse,items 與 "驗簽、攤平、去重" 一對一同序
const sources = $('驗簽、攤平、去重').all();
const out = [];

$input.all().forEach((item, i) => {
  const psid = sources[i]?.json.psid;
  if (!psid) return;

  const status = item.json.statusCode ?? 200;
  const ok = status >= 200 && status < 300;
  const reply = ok ? (item.json.body?.reply ?? '') : '';
  const text = reply.trim() === '' ? FALLBACK : reply;

  splitMessage(text, MESSENGER_LIMIT).forEach((chunk, part) => {
    out.push({ json: { psid, text: chunk, part: part + 1, backendStatus: status } });
  });
});

return out;
